int 
dtb_custdlg_remove_bpanel_msg_initialize(DtbMessageData instance)
{
    char	*tmp_txt;
    if (instance->initialized)
    {
        return 0;
    }
    instance->initialized = True;

    instance->type = XmDIALOG_WARNING;
    instance->title = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 16, 25, "Application Builder"));
    instance->message = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 16, 26, "Removing Button Panel will cause all\nButton Panel children to be deleted."));
    instance->action1_label = XmStringCreateLocalized(CATGETS(Dtb_project_catd, 16, 27, "Remove"));
    instance->action1_callback = (XtCallbackProc) NULL;
    instance->action2_label = (XmString) NULL;
    instance->action2_callback = (XtCallbackProc) NULL;
    instance->action3_label = (XmString) NULL;
    instance->action3_callback = (XtCallbackProc) NULL;
    instance->cancel_button = True;
    instance->cancel_callback = (XtCallbackProc) NULL;
    instance->help_button = True;
    tmp_txt = CATGETS(Dtb_project_catd, 16, 51, "If the button panel is removed, any changes made\nto the button panel (additional objects or changes\nto the defaults) will also be deleted. You have\nthe option of continuing with the deletion or\ncancelling the operation.\n");
    instance->help_data.help_text = XtMalloc(strlen(tmp_txt)+1);
    strcpy(instance->help_data.help_text, tmp_txt);
    
    instance->help_data.help_volume = "";
    instance->help_data.help_locationID = "";
    instance->default_button = DTB_CANCEL_BUTTON;
    return 0;
}

